        Unsafe.Add(ref bf1, 12) = Hb(cospi[50], Unsafe.Add(ref bf0, 12), cospi[14], Unsafe.Add(ref bf0, 13), cosBit);
        Unsafe.Add(ref bf1, 13) = Hb(cospi[14], Unsafe.Add(ref bf0, 12), -cospi[50], Unsafe.Add(ref bf0, 13), cosBit);
        Unsafe.Add(ref bf1, 14) = Hb(cospi[58], Unsafe.Add(ref bf0, 14), cospi[6], Unsafe.Add(ref bf0, 15), cosBit);
        Unsafe.Add(ref bf1, 15) = Hb(cospi[6], Unsafe.Add(ref bf0, 14), -cospi[58], Unsafe.Add(ref bf0, 15), cosBit);
        bf0 = ref step;
        bf1 = ref output;
        Unsafe.Add(ref bf1, 0) = Unsafe.Add(ref bf0, 1);
        Unsafe.Add(ref bf1, 1) = Unsafe.Add(ref bf0, 14);
        Unsafe.Add(ref bf1, 2) = Unsafe.Add(ref bf0, 3);
        Unsafe.Add(ref bf1, 3) = Unsafe.Add(ref bf0, 12);
        Unsafe.Add(ref bf1, 4) = Unsafe.Add(ref bf0, 5);
        Unsafe.Add(ref bf1, 5) = Unsafe.Add(ref bf0, 10);
        Unsafe.Add(ref bf1, 6) = Unsafe.Add(ref bf0, 7);
        Unsafe.Add(ref bf1, 7) = Unsafe.Add(ref bf0, 8);
        Unsafe.Add(ref bf1, 8) = Unsafe.Add(ref bf0, 9);
        Unsafe.Add(ref bf1, 9) = Unsafe.Add(ref bf0, 6);
        Unsafe.Add(ref bf1, 10) = Unsafe.Add(ref bf0, 11);
        Unsafe.Add(ref bf1, 11) = Unsafe.Add(ref bf0, 4);
        Unsafe.Add(ref bf1, 12) = Unsafe.Add(ref bf0, 13);
        Unsafe.Add(ref bf1, 13) = Unsafe.Add(ref bf0, 2);
        Unsafe.Add(ref bf1, 14) = Unsafe.Add(ref bf0, 15);
        Unsafe.Add(ref bf1, 15) = Unsafe.Add(ref bf0, 0);
    }

    private static void Fadst4(ref V input, ref V output, int cosBit)
    {
        var sinpi = SinPi(cosBit);
        V x0 = input, x1 = Unsafe.Add(ref input, 1), x2 = Unsafe.Add(ref input, 2), x3 = Unsafe.Add(ref input, 3);
        V s0 = Vector256.Create(sinpi[1]) * x0, s1 = Vector256.Create(sinpi[4]) * x0;
        V s2 = Vector256.Create(sinpi[2]) * x1, s3 = Vector256.Create(sinpi[1]) * x1;
        V s4 = Vector256.Create(sinpi[3]) * x2, s5 = Vector256.Create(sinpi[4]) * x3, s6 = Vector256.Create(sinpi[2]) * x3;
        V s7 = x0 + x1;
        s7 = s7 - x3;
        x0 = s0 + s2; x1 = Vector256.Create(sinpi[3]) * s7; x2 = s1 - s3; x3 = s4;
        x0 = x0 + s5; x2 = x2 + s6;
        s0 = x0 + x3; s1 = x1; s2 = x2 - x3; s3 = x2 - x0;
        s3 = s3 + x3;
        var rnd = Vector256.Create(1 << (cosBit - 1));
        output = Vector256.ShiftRightArithmetic(s0 + rnd, cosBit);
        Unsafe.Add(ref output, 1) = Vector256.ShiftRightArithmetic(s1 + rnd, cosBit);
        Unsafe.Add(ref output, 2) = Vector256.ShiftRightArithmetic(s2 + rnd, cosBit);
        Unsafe.Add(ref output, 3) = Vector256.ShiftRightArithmetic(s3 + rnd, cosBit);
    }

    private static void Fidentity(ref V input, ref V output, int n)
    {
        for (int i = 0; i < n; i++)
        {
            V x = Unsafe.Add(ref input, i);
            Unsafe.Add(ref output, i) = n switch
            {
                4 => MulRound(x, 5793, 12),                 // x * NewSqrt2
                8 => x + x,                                 // x * 2
                16 => MulRound(x, 2 * 5793, 12),            // x * 2 * NewSqrt2
                _ => Vector256.ShiftLeft(x, 2),             // x * 4
            };
        }
    }

    // 1D kinds as Av1InvTransform.Type1dDct / Type1dAdst / Type1dIdentity
    private static void Txfm1d(int kind, int n, ref V input, ref V output, int cosBit)
    {
        if (kind == Av1InvTransform.Type1dIdentity) { Fidentity(ref input, ref output, n); return; }
        if (kind == Av1InvTransform.Type1dAdst)
        {
            if (n == 4) Fadst4(ref input, ref output, cosBit); else if (n == 8) Fadst8(ref input, ref output, cosBit); else Fadst16(ref input, ref output, cosBit);
            return;
        }
        switch (n)
        {
            case 4: Fdct4(ref input, ref output, cosBit); break;
            case 8: Fdct8(ref input, ref output, cosBit); break;
            case 16: Fdct16(ref input, ref output, cosBit); break;
            case 32: Fdct32(ref input, ref output, cosBit); break;
            default: Fdct64(ref input, ref output, cosBit); break;
        }
    }

    // av1_fwd_txfm_shift_ls / av1_fwd_cos_bit_col / _row (tx size order = Av1TxSize)
    private static readonly sbyte[] Shift = { 2, 0, 0, 2, -1, 0, 2, -2, 0, 2, -4, 0, 0, -2, -2, 2, -1, 0, 2, -1, 0, 2, -2, 0, 2, -2, 0,
        2, -4, 0, 2, -4, 0, 0, -2, -2, 2, -4, -2, 2, -1, 0, 2, -1, 0, 2, -2, 0, 2, -2, 0, 0, -2, 0, 2, -4, 0 };
    private static readonly sbyte[] CosBitCol = { 13, 13, 13, 0, 0, 13, 13, 13, 12, 0, 13, 13, 13, 12, 13, 0, 13, 13, 12, 13, 0, 0, 13, 12, 13 };
    private static readonly sbyte[] CosBitRow = { 13, 13, 12, 0, 0, 13, 13, 13, 12, 0, 13, 13, 12, 13, 12, 0, 12, 13, 12, 11, 0, 0, 12, 11, 10 };

    // 8 x 8 transpose of the 32-bit lanes of r0..r7 (in place)
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Transpose8(ref V r)
    {
        V a0 = r, a1 = Unsafe.Add(ref r, 1), a2 = Unsafe.Add(ref r, 2), a3 = Unsafe.Add(ref r, 3);
        V a4 = Unsafe.Add(ref r, 4), a5 = Unsafe.Add(ref r, 5), a6 = Unsafe.Add(ref r, 6), a7 = Unsafe.Add(ref r, 7);
        V t0 = Avx2.UnpackLow(a0, a1), t1 = Avx2.UnpackHigh(a0, a1), t2 = Avx2.UnpackLow(a2, a3), t3 = Avx2.UnpackHigh(a2, a3);
        V t4 = Avx2.UnpackLow(a4, a5), t5 = Avx2.UnpackHigh(a4, a5), t6 = Avx2.UnpackLow(a6, a7), t7 = Avx2.UnpackHigh(a6, a7);
        V u0 = Avx2.UnpackLow(t0.AsInt64(), t2.AsInt64()).AsInt32(), u1 = Avx2.UnpackHigh(t0.AsInt64(), t2.AsInt64()).AsInt32();
        V u2 = Avx2.UnpackLow(t1.AsInt64(), t3.AsInt64()).AsInt32(), u3 = Avx2.UnpackHigh(t1.AsInt64(), t3.AsInt64()).AsInt32();
        V u4 = Avx2.UnpackLow(t4.AsInt64(), t6.AsInt64()).AsInt32(), u5 = Avx2.UnpackHigh(t4.AsInt64(), t6.AsInt64()).AsInt32();
        V u6 = Avx2.UnpackLow(t5.AsInt64(), t7.AsInt64()).AsInt32(), u7 = Avx2.UnpackHigh(t5.AsInt64(), t7.AsInt64()).AsInt32();
        r = Avx2.Permute2x128(u0, u4, 0x20); Unsafe.Add(ref r, 1) = Avx2.Permute2x128(u1, u5, 0x20);
        Unsafe.Add(ref r, 2) = Avx2.Permute2x128(u2, u6, 0x20); Unsafe.Add(ref r, 3) = Avx2.Permute2x128(u3, u7, 0x20);
        Unsafe.Add(ref r, 4) = Avx2.Permute2x128(u0, u4, 0x31); Unsafe.Add(ref r, 5) = Avx2.Permute2x128(u1, u5, 0x31);
        Unsafe.Add(ref r, 6) = Avx2.Permute2x128(u2, u6, 0x31); Unsafe.Add(ref r, 7) = Avx2.Permute2x128(u3, u7, 0x31);
    }

    /// <summary>libaom's forward transform of a w x h residual (row-major, stride w) with 1D kinds hKind (rows) / vKind
    /// (columns), quantised as libaom's quantiser sees it: qf = c * 2^tx_scale / dq (dc for rc 0), level = |qf| + 0.5 - bias
    /// floored (0 below 1), in the decoder's layout rc = ky + kx * min(h, 32) (the retained 32 x 32 of 64-point axes).</summary>
    [SkipLocalsInit]
    internal static void ForwardQuant(ReadOnlySpan<int> residual, int w, int h, int txSize, int hKind, int vKind,
        double dcDq, double acDq, double bias, int[] levels, double[]? qfOut)
    {
        int lw = System.Numerics.BitOperations.Log2((uint)w) - 2, lh = System.Numerics.BitOperations.Log2((uint)h) - 2;
        int sh0 = Shift[txSize * 3], sh1 = -Shift[txSize * 3 + 1], sh2 = -Shift[txSize * 3 + 2];
        int cosCol = CosBitCol[lw * 5 + lh], cosRow = CosBitRow[lw * 5 + lh];
        bool rect2 = w == 2 * h || h == 2 * w;
        int sw = Math.Min(w, 32), sh = Math.Min(h, 32), ng = (w + 7) >> 3;
        int pels = w * h;
        double scale = 1 << ((pels > 256 ? 1 : 0) + (pels > 1024 ? 1 : 0));
        // column pass: group g holds columns 8g..8g+7 as lanes, one vector per row (rows past h stay zero for 4-tall)
        int hp = Math.Max(h, 8);
        Span<V> colS = stackalloc V[ng * hp + 64];
        ref V col = ref MemoryMarshal.GetReference(colS);
        ref V tmp = ref Unsafe.Add(ref col, ng * hp);           // 64 vectors of scratch
        ref int res0 = ref MemoryMarshal.GetReference(residual);
        var rnd1 = Vector256.Create(sh1 > 0 ? 1 << (sh1 - 1) : 0);
        for (int g = 0; g < ng; g++)
        {
            ref V cg = ref Unsafe.Add(ref col, g * hp);
            for (int r = 0; r < h; r++)
            {
                ref int p = ref Unsafe.Add(ref res0, r * w + g * 8);
                V v = w >= 8 ? Vector256.LoadUnsafe(ref p) : Vector256.Create(Vector128.LoadUnsafe(ref p), Vector128<int>.Zero);
                Unsafe.Add(ref tmp, r) = Vector256.ShiftLeft(v, sh0);
            }
            Txfm1d(vKind, h, ref tmp, ref cg, cosCol);
            for (int r = 0; r < h; r++)
            {
                ref V o = ref Unsafe.Add(ref cg, r);
                if (sh1 > 0) o = Vector256.ShiftRightArithmetic(o + rnd1, sh1);
            }
            for (int r = h; r < hp; r++) Unsafe.Add(ref cg, r) = V.Zero;
        }
        // row pass, 8 rows at a time (rows past 32 of a 64-tall block are discarded, so not transformed)
        Span<V> rinS = stackalloc V[64];
        ref V rin = ref MemoryMarshal.GetReference(rinS);
        var rnd2 = Vector256.Create(sh2 > 0 ? 1 << (sh2 - 1) : 0);
        var vdc = Vector256.Create(scale / dcDq, scale / acDq, scale / acDq, scale / acDq); var vac = Vector256.Create(scale / acDq);
        var half = Vector256.Create(0.5); var vbias = Vector256.Create(bias); var one = Vector256.Create(1.0);
        ref int lv0 = ref MemoryArrayRef(levels);
        for (int r0 = 0; r0 < sh; r0 += 8)
        {
            for (int g = 0; g < ng; g++)
            {
                // rows r0..r0+7 of column group g, transposed: rin[8g + j] = column 8g + j, lanes = rows
                ref V src = ref Unsafe.Add(ref col, g * hp + r0);
                ref V dst = ref Unsafe.Add(ref rin, g * 8);
                for (int j = 0; j < 8; j++) Unsafe.Add(ref dst, j) = Unsafe.Add(ref src, j);
                Transpose8(ref dst);
            }
            Txfm1d(hKind, w, ref rin, ref tmp, cosRow);
            int nr = Math.Min(8, h - r0);
            for (int c = 0; c < sw; c++)
            {
                V v = Unsafe.Add(ref tmp, c);
                if (sh2 > 0) v = Vector256.ShiftRightArithmetic(v + rnd2, sh2);
                if (rect2) v = MulRound(v, 5793, 12);
                int rc = c * sh + r0;
                Quant4(Avx.ConvertToVector256Double(v.GetLower()), rc == 0 ? vdc : vac, half, vbias, one, ref Unsafe.Add(ref lv0, rc), qfOut, rc);
                if (nr == 8)
                    Quant4(Avx.ConvertToVector256Double(v.GetUpper()), vac, half, vbias, one, ref Unsafe.Add(ref lv0, rc + 4), qfOut, rc + 4);
            }
        }
    }

    private static ref int MemoryArrayRef(int[] a) => ref MemoryMarshal.GetArrayDataReference(a);

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void Quant4(Vector256<double> c, Vector256<double> mul, Vector256<double> half,
        Vector256<double> bias, Vector256<double> one, ref int dst, double[]? qfOut, int at)
    {
        var qf = c * mul;   // c * 2^tx_scale / dq
        if (qfOut != null) qf.StoreUnsafe(ref MemoryMarshal.GetArrayDataReference(qfOut), (nuint)at);
        var mag = Vector256.Abs(qf) + half - bias;
        var fl = Vector256.Floor(mag);
        var sgn = Vector256.ConditionalSelect(Vector256.LessThan(qf, Vector256<double>.Zero), -fl, fl);
        var lv = Vector256.ConditionalSelect(Vector256.LessThan(mag, one), Vector256<double>.Zero, sgn);
        Avx.ConvertToVector128Int32WithTruncation(lv).StoreUnsafe(ref dst);
    }
}
